from AlgorithmImports import *
import math


class CrossAndStreakAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.pending_orders = {}
        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        spy_close = None
        aapl_close = None

        if self.spy in data.Bars:
            spy_bar = data.Bars[self.spy]
            spy_close = float(spy_bar.Close)
            self.spy_sma.Update(spy_bar.EndTime, spy_close)

        if self.aapl in data.Bars:
            aapl_bar = data.Bars[self.aapl]
            aapl_close = float(aapl_bar.Close)
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close

        spy_crosses_above = False
        spy_crosses_below = False

        if spy_close is not None and self.spy_sma.IsReady:
            current_sma = float(self.spy_sma.Current.Value)

            if self.spy_previous_close is not None and self.spy_previous_sma is not None:
                spy_crosses_above = (
                    self.spy_previous_close <= self.spy_previous_sma
                    and spy_close > current_sma
                )
                spy_crosses_below = (
                    self.spy_previous_close >= self.spy_previous_sma
                    and spy_close < current_sma
                )

            self.spy_previous_close = spy_close
            self.spy_previous_sma = current_sma

        if self.IsWarmingUp:
            return

        if not all(symbol in data.Bars for symbol in self.symbols):
            return

        if spy_crosses_below and self.strategy_a_lot > 0:
            self._submit_sell("A", self.spy, self.strategy_a_lot)

        if (
            aapl_close is not None
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
            and self.strategy_b_lot > 0
        ):
            self._submit_sell("B", self.aapl, self.strategy_b_lot)

        if (
            spy_crosses_above
            and self.spy_sma.IsReady
            and self.strategy_a_lot == 0
            and "A" not in self.pending_orders
        ):
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = int(math.floor(target_value / spy_close))
            if quantity > 0:
                self._submit_buy("A", self.spy, quantity)

        if (
            aapl_close is not None
            and self.aapl_rsi.IsReady
            and self.aapl_red_streak >= 3
            and self.strategy_b_lot == 0
            and "B" not in self.pending_orders
            and float(self.Portfolio.Cash) >= 20000
        ):
            quantity = int(math.floor(20000 / aapl_close))
            if quantity > 0:
                self._submit_buy("B", self.aapl, quantity)

    def _submit_buy(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity, tag=f"{strategy}_BUY")
        self.pending_orders[strategy] = {
            "order_id": ticket.OrderId,
            "side": "BUY"
        }

    def _submit_sell(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, -quantity, tag=f"{strategy}_SELL")
        self.pending_orders[strategy] = {
            "order_id": ticket.OrderId,
            "side": "SELL"
        }

    def OnOrderEvent(self, order_event: OrderEvent):
        order_id = order_event.OrderId
        strategy = None
        order_info = None

        for key, value in self.pending_orders.items():
            if value["order_id"] == order_id:
                strategy = key
                order_info = value
                break

        if strategy is None:
            return

        fill_quantity = int(order_event.FillQuantity)

        if fill_quantity != 0:
            if order_info["side"] == "BUY":
                if strategy == "A":
                    self.strategy_a_lot += fill_quantity
                else:
                    self.strategy_b_lot += fill_quantity
            else:
                sold_quantity = abs(fill_quantity)
                if strategy == "A":
                    self.strategy_a_lot = max(0, self.strategy_a_lot - sold_quantity)
                else:
                    self.strategy_b_lot = max(0, self.strategy_b_lot - sold_quantity)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            del self.pending_orders[strategy]
